from __future__ import annotations

import re
from dataclasses import dataclass

_VERSION_RE = re.compile(
    r"(?P<major>0|[1-9][0-9]*)\."
    r"(?P<minor>0|[1-9][0-9]*)\."
    r"(?P<patch>0|[1-9][0-9]*)"
    r"(?:-(?P<prerelease>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

_NUMERIC_RE = re.compile(r"[0-9]+")

_RANGE_OPERATORS = ("<=", ">=", ">", "<", "=", "^", "~")


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise TypeError("version must be a string")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    prerelease_text = match.group("prerelease")
    prerelease = tuple(prerelease_text.split(".")) if prerelease_text else ()
    for identifier in prerelease:
        if (
            _NUMERIC_RE.fullmatch(identifier) is not None
            and len(identifier) > 1
            and identifier[0] == "0"
        ):
            raise ValueError(f"invalid version: {text!r}")

    build_text = match.group("build")
    build = tuple(build_text.split(".")) if build_text else ()

    return Version(
        major=int(match.group("major")),
        minor=int(match.group("minor")),
        patch=int(match.group("patch")),
        prerelease=prerelease,
        build=build,
    )


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    if isinstance(value, str):
        return parse(value)
    raise TypeError("version must be a string or Version")


def _compare_versions(a: Version, b: Version) -> int:
    for left, right in (
        (a.major, b.major),
        (a.minor, b.minor),
        (a.patch, b.patch),
    ):
        if left != right:
            return -1 if left < right else 1

    if not a.prerelease and not b.prerelease:
        return 0
    if not a.prerelease:
        return 1
    if not b.prerelease:
        return -1

    for left, right in zip(a.prerelease, b.prerelease):
        left_numeric = _NUMERIC_RE.fullmatch(left) is not None
        right_numeric = _NUMERIC_RE.fullmatch(right) is not None

        if left_numeric and right_numeric:
            left_value = int(left)
            right_value = int(right)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        elif left != right:
            return -1 if left < right else 1

    if len(a.prerelease) != len(b.prerelease):
        return -1 if len(a.prerelease) < len(b.prerelease) else 1
    return 0


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_versions(_as_version(a), _as_version(b))


def _expand_comparator(
    operator: str, version: Version
) -> list[tuple[str, Version]]:
    if operator in ("", "="):
        return [("==", version)]
    if operator in (">", ">=", "<", "<="):
        return [(operator, version)]
    if operator == "^":
        if version.major != 0:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor != 0:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return [(">=", version), ("<", upper)]
    if operator == "~":
        upper = Version(version.major, version.minor + 1, 0)
        return [(">=", version), ("<", upper)]
    raise ValueError(f"invalid range operator: {operator!r}")


def _parse_range(range_: str) -> list[list[tuple[str, Version]]]:
    if not isinstance(range_, str):
        raise ValueError("range must be a string")

    sets: list[list[tuple[str, Version]]] = []
    for part in range_.split("||"):
        text = part.strip()
        if not text:
            raise ValueError(f"invalid range: {range_!r}")

        comparators: list[tuple[str, Version]] = []
        for token in text.split():
            operator = ""
            remainder = token
            for candidate in _RANGE_OPERATORS:
                if token.startswith(candidate):
                    operator = candidate
                    remainder = token[len(candidate) :]
                    break

            if not remainder:
                raise ValueError(f"invalid range: {range_!r}")

            try:
                version = parse(remainder)
            except (TypeError, ValueError):
                raise ValueError(f"invalid range: {range_!r}") from None

            comparators.extend(_expand_comparator(operator, version))

        sets.append(comparators)

    return sets


def _satisfies_set(
    version: Version, comparators: list[tuple[str, Version]]
) -> bool:
    if version.prerelease:
        core = (version.major, version.minor, version.patch)
        if not any(
            (other.prerelease and (other.major, other.minor, other.patch) == core)
            for _, other in comparators
        ):
            return False

    for operator, other in comparators:
        result = _compare_versions(version, other)
        if operator == "==":
            if result != 0:
                return False
        elif operator == ">":
            if result <= 0:
                return False
        elif operator == ">=":
            if result < 0:
                return False
        elif operator == "<":
            if result >= 0:
                return False
        elif operator == "<=":
            if result > 0:
                return False
        else:  # pragma: no cover - _expand_comparator only returns the above
            raise ValueError(f"invalid range operator: {operator!r}")

    return True


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed_version = _as_version(version)
    return any(
        _satisfies_set(parsed_version, comparators)
        for comparators in _parse_range(range_)
    )

